:root{--bg:#090909;--panel:#121212;--gold:#d7b36a;--gold2:#f3d99b;--muted:#aaa;--line:rgba(215,179,106,.24);--white:#f7f5f0}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--white);font-family:Inter,Arial,sans-serif}button,a{font:inherit}a{color:inherit;text-decoration:none}.wrap{width:min(1180px,92%);margin:auto}
.topbar{height:38px;display:flex;align-items:center;justify-content:center;background:#17130c;color:var(--gold2);font-size:11px;letter-spacing:2px;text-transform:uppercase;border-bottom:1px solid var(--line)}
nav{height:78px;display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid rgba(255,255,255,.08);background:rgba(9,9,9,.96);position:sticky;top:0;z-index:10;padding:0 max(4%,calc((100% - 1180px)/2))}
.brand{font-size:24px;font-weight:900;letter-spacing:4px}.brand span{color:var(--gold)}.navlinks{display:flex;gap:28px;font-size:13px;color:#ddd}.navlinks a:hover{color:var(--gold)}.nav-actions{display:flex;gap:10px;align-items:center}.iconbtn{border:1px solid var(--line);color:var(--gold2);background:#141414;border-radius:999px;padding:10px 15px;cursor:pointer}.cart-count{display:inline-flex;min-width:20px;height:20px;align-items:center;justify-content:center;border-radius:50%;background:var(--gold);color:#111;font-size:11px;font-weight:bold;margin-left:5px}
.hero{min-height:590px;display:flex;align-items:center;position:relative;overflow:hidden;background:#090909 url('data:image/png;base64,') center/cover no-repeat}
.hero:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.72) 0%,rgba(0,0,0,.4) 43%,rgba(0,0,0,.05) 100%)}
.hero-content{position:relative;z-index:1;width:min(1180px,92%);margin:auto;padding:70px 0;max-width:1180px;display:flex;flex-direction:column;align-items:flex-end;text-align:right}.hero-content .eyebrow{max-width:520px}.hero-content h1{max-width:530px}.hero-content p{margin-left:auto}.hero-buttons{justify-content:flex-end}.eyebrow{color:var(--gold2);font-size:11px;letter-spacing:4px;text-transform:uppercase}.hero h1{font-size:clamp(42px,6vw,76px);line-height:1.02;letter-spacing:-2px;max-width:530px;margin:18px 0}.hero h1 em{font-style:normal;color:var(--gold)}.hero p{max-width:390px;line-height:1.8;color:#e1ddd5;font-size:15px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:14px 22px;border-radius:4px;font-weight:750;font-size:12px;letter-spacing:1px;text-transform:uppercase;cursor:pointer;transition:.2s;border:1px solid var(--gold);background:var(--gold);color:#111}.btn:hover{background:var(--gold2);transform:translateY(-2px)}.btn-outline{background:transparent;color:var(--gold2)}.hero-buttons{display:flex;gap:12px;flex-wrap:wrap;margin-top:28px}
.features{border-top:1px solid var(--line);border-bottom:1px solid var(--line);background:#0e0e0e}.feature-row{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;padding:22px 0}.feature{display:flex;align-items:center;gap:13px;justify-content:center}.feature-icon{color:var(--gold);font-size:23px}.feature strong{display:block;font-size:12px;letter-spacing:.8px}.feature small{display:block;color:var(--muted);font-size:11px;margin-top:5px}
section{padding:84px 0}.section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:30px}.kicker{font-size:10px;color:var(--gold);letter-spacing:3px;text-transform:uppercase}.section-head h2{font-size:clamp(28px,4vw,42px);margin:10px 0 0;letter-spacing:-1px}.section-head p{max-width:340px;color:var(--muted);font-size:13px;line-height:1.7;margin:0}
.catalog-shell{position:relative}.catalog{display:grid;grid-auto-flow:column;grid-auto-columns:calc((100% - 48px)/3);gap:24px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:thin;scrollbar-color:var(--gold) #222;padding:4px 2px 20px;scroll-behavior:smooth}.product{scroll-snap-align:start;background:linear-gradient(145deg,#171717,#0f0f0f);border:1px solid rgba(255,255,255,.08);border-radius:8px;overflow:hidden;transition:.25s}.product:hover{border-color:var(--line);transform:translateY(-4px)}.product-image{height:270px;position:relative;display:flex;align-items:center;justify-content:center;background:radial-gradient(ellipse at center,#28231a 0%,#111 68%);overflow:hidden}.product-image img{width:100%;height:100%;object-fit:cover;transition:transform .5s;opacity:.94}.product:hover .product-image img{transform:scale(1.05)}.tag{position:absolute;top:14px;left:14px;background:var(--gold);color:#111;font-size:9px;font-weight:800;letter-spacing:1px;padding:7px 9px;border-radius:2px}.product-info{padding:20px}.product-type{font-size:10px;color:var(--gold);letter-spacing:2px;text-transform:uppercase}.product h3{font-size:18px;margin:9px 0}.desc{color:#aaa;font-size:12px;line-height:1.6;min-height:38px}.price-row{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:17px 0}.price{font-size:19px;font-weight:800;color:var(--gold2)}.old-price{font-size:11px;color:#777;text-decoration:line-through;margin-left:7px}.product-actions{display:flex;gap:8px}.product-actions button{flex:1;padding:11px 8px;font-size:10px;letter-spacing:.5px}.add-btn{background:transparent;color:var(--gold2);border:1px solid var(--line);border-radius:3px;cursor:pointer}.add-btn:hover{background:#211b10}.slider-controls{display:flex;gap:8px}.arrow{height:40px;width:40px;border:1px solid var(--line);background:#141414;color:var(--gold);border-radius:50%;cursor:pointer;font-size:20px}.arrow:hover{background:var(--gold);color:#111}
.promo{background:linear-gradient(110deg,#211a0e,#111 70%);border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.promo-inner{display:flex;align-items:center;justify-content:space-between;gap:30px}.promo h2{font-size:clamp(26px,4vw,40px);margin:12px 0}.promo p{color:#bbb;line-height:1.7;font-size:13px;max-width:560px}.promo-mark{font-size:90px;color:rgba(215,179,106,.16);font-weight:900;letter-spacing:-8px}
.about-grid{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}.about-grid h2{font-size:40px;margin:12px 0}.about-grid p{color:#aaa;line-height:1.9;font-size:14px}.about-card{padding:35px;border:1px solid var(--line);background:linear-gradient(135deg,#19150e,#101010);border-radius:8px}.about-card .big{font-size:48px;color:var(--gold);font-weight:900}.about-card p{font-size:13px}
footer{border-top:1px solid var(--line);padding:38px 0;background:#070707}.footer-row{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.footer-note{color:#777;font-size:11px;line-height:1.8}.social{display:flex;gap:12px;align-items:center}.social a{color:var(--gold2);font-size:12px}
.wa-float{position:fixed;bottom:22px;right:22px;z-index:20;background:#20c763;color:white;width:58px;height:58px;border-radius:50%;display:flex;align-items:center;justify-content:center;box-shadow:0 8px 28px #0009;border:2px solid #fff3}.wa-float svg{width:29px;height:29px}
.toast{position:fixed;bottom:95px;right:22px;z-index:30;background:#1b1b1b;border:1px solid var(--gold);color:var(--white);padding:13px 18px;border-radius:5px;font-size:12px;box-shadow:0 10px 30px #0008;opacity:0;transform:translateY(10px);pointer-events:none;transition:.25s}.toast.show{opacity:1;transform:translateY(0)}
.modal-backdrop{position:fixed;inset:0;background:#000b;z-index:40;display:none;align-items:center;justify-content:center;padding:18px}.modal-backdrop.open{display:flex}.modal{width:min(520px,100%);max-height:85vh;overflow:auto;background:#111;border:1px solid var(--line);border-radius:8px;padding:25px}.modal-head{display:flex;align-items:center;justify-content:space-between}.modal h2{margin:0;color:var(--gold2)}.close{background:none;border:0;color:#ddd;font-size:26px;cursor:pointer}.cart-items{margin:20px 0}.cart-item{display:flex;justify-content:space-between;gap:15px;padding:13px 0;border-bottom:1px solid #292929;font-size:13px}.cart-item small{display:block;color:#999;margin-top:5px}.qty{display:flex;align-items:center;gap:8px}.qty button{background:#222;color:var(--gold);border:1px solid #444;width:25px;height:25px;cursor:pointer}.cart-total{display:flex;justify-content:space-between;padding:15px 0;font-weight:bold}.empty{color:#999;font-size:13px;padding:20px 0}.checkout{width:100%;margin-top:8px}
@media(max-width:800px){.navlinks{display:none}.hero{min-height:520px;background-position:42% center}.hero:before{background:linear-gradient(90deg,#000c,#0007 65%,#0003)}.catalog{grid-auto-columns:calc((100% - 18px)/2);gap:18px}.product-image{height:235px}.about-grid{grid-template-columns:1fr;gap:25px}.promo-mark{display:none}}
@media(max-width:520px){nav{height:68px}.brand{font-size:19px;letter-spacing:2px}.iconbtn{padding:9px 11px;font-size:11px}.hero h1{font-size:43px}.hero p{font-size:13px}.feature-row{grid-template-columns:1fr;gap:16px}.feature{justify-content:flex-start}.feature-row{padding:20px 4%}.catalog{grid-auto-columns:86%;gap:14px}.product-image{height:270px}section{padding:60px 0}.section-head{align-items:flex-start}.section-head p{display:none}.promo-inner{align-items:flex-start;flex-direction:column}.about-grid h2{font-size:32px}.footer-row{align-items:flex-start;flex-direction:column}}

/* ROMORA KOPER modern refresh */
:root{--bg:#080808;--panel:#111;--gold:#d8b66b;--gold2:#f4dfaa;--line:rgba(216,182,107,.25)}
body{letter-spacing:.1px;background:radial-gradient(ellipse at 85% 0%,#1c1710 0%,#080808 38%)}
nav{backdrop-filter:blur(18px);background:rgba(8,8,8,.88);border-bottom-color:rgba(216,182,107,.16)}
.brand{letter-spacing:3px}.brand span{background:linear-gradient(110deg,#f7e7b9,#b88b3b);-webkit-background-clip:text;background-clip:text;color:transparent}
.hero{min-height:650px;background-position:center 58%}
.hero:before{background:linear-gradient(90deg,rgba(0,0,0,.12) 0%,rgba(0,0,0,.3) 48%,rgba(0,0,0,.92) 100%)}
.hero-content{max-width:1180px;padding:80px 0}
.hero h1{font-size:clamp(48px,6.5vw,88px);line-height:.98;letter-spacing:-3px}
.hero p{color:#d0cbc1;max-width:420px}
.btn{border-radius:999px;padding:15px 24px;box-shadow:0 7px 25px rgba(216,182,107,.08)}
.btn-outline{border-color:rgba(244,223,170,.5)}
.features{background:rgba(15,15,15,.75);backdrop-filter:blur(10px)}
.feature{justify-content:center}
section{padding:96px 0}
.section-head h2{font-size:clamp(32px,4vw,48px);letter-spacing:-1.8px}
.catalog{grid-auto-columns:calc((100% - 54px)/3);gap:27px;scrollbar-width:none;padding:4px 2px 24px}
.catalog::-webkit-scrollbar{display:none}
.product{border-radius:14px;background:linear-gradient(145deg,#181818,#0d0d0d);border-color:rgba(255,255,255,.07);box-shadow:0 16px 40px #0002}
.product-image{height:330px;background:#f7f6f3}
.product-image img{object-fit:contain;padding:8px;mix-blend-mode:multiply;opacity:1}
.tag{border-radius:999px;letter-spacing:1.4px}
.product-info{padding:22px}
.product h3{font-size:20px;letter-spacing:-.4px}
.product-type{letter-spacing:1.8px}
.product-actions button{border-radius:999px}
.add-btn{border-color:rgba(216,182,107,.5)}
.arrow{transition:.2s}.arrow:hover{transform:translateY(-2px)}
.promo{background:radial-gradient(ellipse at 10% 50%,#29200f,#0c0c0c 70%)}
.promo-inner{padding:12px 0}
.about-card{border-radius:14px;box-shadow:0 20px 55px #0004}
.wa-float{width:62px;height:62px;transition:transform .2s}.wa-float:hover{transform:scale(1.07)}
.modal{border-radius:16px;box-shadow:0 25px 100px #0009}
@media(max-width:800px){.catalog{grid-auto-columns:calc((100% - 18px)/2);gap:18px}.product-image{height:285px}.hero{background-position:42% center}}
@media(max-width:520px){.hero{min-height:560px;background-position:42% center}.hero h1{font-size:48px}.catalog{grid-auto-columns:86%;gap:14px}.product-image{height:300px}section{padding:68px 0}}


.empty-product-art{height:100%;min-height:280px;width:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;background:linear-gradient(145deg,#181818,#0c0c0c);color:#d8b66b;border:1px dashed rgba(216,182,107,.25)}
.empty-product-art span{font-weight:800;letter-spacing:5px;font-size:20px}
.empty-product-art small{font-size:10px;letter-spacing:3px;color:#8f805f}
/* Foto katalog dari unggahan pengguna */
.product-art { overflow: hidden; background: #f7f6f2; }
.product-art > img { display:block; width:100%; height:100%; min-height:290px; object-fit:contain; padding:8px; mix-blend-mode:multiply; }
@media(max-width:760px) { .product-art > img { min-height:260px; } }
